(324, '_site_transient_g_url_details_response_5b181fb22cc30ef3714e7e89dcf86f75', '<!DOCTYPE html>\n	<html lang=\"id\">\n	<head>\n	<meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />\n	<title>Log Masuk &lsaquo; jejak digital &#8212; WordPress</title>\n	<meta name=\'robots\' content=\'max-image-preview:large, noindex, noarchive\' />\n<link rel=\'stylesheet\' href=\'http://localhost/literasi/wp-admin/load-styles.php?c=1&amp;dir=ltr&amp;load%5Bchunk_0%5D=dashicons,buttons,forms,l10n,wp-base-styles,wp-tooltip,login&amp;ver=7.1.4\' media=\'all\' />\n	<meta name=\'referrer\' content=\'strict-origin-when-cross-origin\' />\n		<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n	<link rel=\"icon\" href=\"http://localhost/literasi/wp-content/themes/osteo-care/assets/images/2026/03/stethoscope.svg\" sizes=\"32x32\" />\n<link rel=\"icon\" href=\"http://localhost/literasi/wp-content/themes/osteo-care/assets/images/2026/03/stethoscope.svg\" sizes=\"192x192\" />\n<link rel=\"apple-touch-icon\" href=\"http://localhost/literasi/wp-content/themes/osteo-care/assets/images/2026/03/stethoscope.svg\" />\n<meta name=\"msapplication-TileImage\" content=\"http://localhost/literasi/wp-content/themes/osteo-care/assets/images/2026/03/stethoscope.svg\" />\n	</head>\n	<body class=\"login no-js login-action-login wp-core-ui admin-color-modern locale-id-id\">\n	<script>\ndocument.body.className = document.body.className.replace(\'no-js\',\'js\');\n</script>\n\n				<h1 class=\"screen-reader-text\">Log Masuk</h1>\n			<div id=\"login\">\n		<h1 role=\"presentation\" class=\"wp-login-logo\"><a href=\"https://wordpress.org/\">Dipersembahkan oleh WordPress</a></h1>\n	\n		<form name=\"loginform\" id=\"loginform\" action=\"http://localhost/literasi/wp-login.php\" method=\"post\">\n			<p>\n				<label for=\"user_login\">Nama Pengguna atau Alamat Email</label>\n				<input type=\"text\" name=\"log\" id=\"user_login\" class=\"input ltr\" value=\"\" size=\"20\" autocapitalize=\"off\" autocomplete=\"username\" required=\"required\" />\n			</p>\n\n			<div class=\"user-pass-wrap\">\n				<label for=\"user_pass\">Sandi</label>\n				<div class=\"wp-pwd\">\n					<input type=\"password\" name=\"pwd\" id=\"user_pass\" class=\"input password-input ltr\" value=\"\" size=\"20\" autocomplete=\"current-password\" spellcheck=\"false\" required=\"required\" />\n					<button type=\"button\" class=\"button button-secondary wp-hide-pw hide-if-no-js\" data-toggle=\"0\" aria-label=\"Tampilkan sandi\">\n						<span class=\"dashicons dashicons-visibility\" aria-hidden=\"true\"></span>\n					</button>\n				</div>\n			</div>\n									<p class=\"forgetmenot\">\n				<input name=\"rememberme\" type=\"checkbox\" id=\"rememberme\" value=\"forever\"  />\n				<label for=\"rememberme\">Ingat Saya</label>\n				<span class=\"wp-tooltip wp-is-toggletip\">\n				<button aria-haspopup=\"dialog\" aria-label=\"Bantuan\" class=\"wp-tooltip__toggle\" popovertarget=\"rememberme-help-toggletip\" type=\"button\"><span aria-hidden=\"true\" class=\"dashicons dashicons-editor-help\"></span></button>\n				<span popover=\"auto\" id=\"rememberme-help-toggletip\" class=\"wp-tooltip__bubble\" role=\"dialog\" aria-label=\"Bantuan\" tabindex=\"-1\" autofocus><span id=\"rememberme-help-toggletip-text\" class=\"wp-tooltip__text\">Selecting &quot;Remember Me&quot; increases the length of time until you&#8217;re asked to log in again on this device. To keep your account secure, use this option only on your personal devices.</span><button type=\"button\" class=\"wp-tooltip__close\" popovertarget=\"rememberme-help-toggletip\" popovertargetaction=\"hide\" aria-label=\"Tutup\"><span class=\"dashicons dashicons-no-alt\" aria-hidden=\"true\"></span></button></span></span>			</p>\n			<p class=\"submit\">\n				<input type=\"submit\" name=\"wp-submit\" id=\"wp-submit\" class=\"button button-primary button-large\" value=\"Log Masuk\" />\n									<input type=\"hidden\" name=\"redirect_to\" value=\"http://localhost/literasi/wp-admin/post.php?post=45&amp;action=edit\" />\n									<input type=\"hidden\" name=\"testcookie\" value=\"1\" />\n			</p>\n		</form>\n\n					<p id=\"nav\">\n				<a class=\"wp-login-lost-password\" href=\"http://localhost/literasi/wp-login.php?action=lostpassword\">Lupa sandi Anda?</a>			</p>\n			<script>\nfunction wp_attempt_focus() {setTimeout( function() {try {d = document.getElementById( \"user_login\" );d.focus(); d.select();} catch( er ) {}}, 200);}\nwp_attempt_focus();\nif ( typeof wpOnload === \'function\' ) { wpOnload() }\n</script>\n		<p id=\"backtoblog\">\n			<a href=\"http://localhost/literasi/\">&larr; Pergi ke jejak digital</a>		</p>\n		<div class=\"privacy-policy-page-link\"><a class=\"privacy-policy-link\" href=\"http://localhost/literasi/index.php/kebijakan-privasi/\" rel=\"privacy-policy\">Kebijakan Privasi</a></div>	</div>\n				<div class=\"language-switcher\">\n				<form id=\"language-switcher\" method=\"get\">\n\n					<label for=\"language-switcher-locales\">\n						Bahasa<span class=\"dashicons dashicons-translation\" aria-hidden=\"true\"></span>\n					</label>\n\n					<select name=\"wp_lang\" id=\"language-switcher-locales\"><option value=\"en_US\" lang=\"en\" data-installed=\"1\">English (United States)</option>\n<option value=\"id_ID\" lang=\"id\" selected=\'selected\' data-installed=\"1\">Bahasa Indonesia</option></select>\n					\n											<input type=\"hidden\" name=\"redirect_to\" value=\"http://localhost/literasi/wp-admin/post.php?post=45&action=edit\" />\n					\n					\n						<input type=\"submit\" class=\"button\" value=\"Ubah\">\n\n					</form>\n				</div>\n			\n	<script>\nvar _zxcvbnSettings = {\"src\":\"http://localhost/literasi/wp-includes/js/zxcvbn.min.js\"};\n//# sourceURL=js-inline-concat-clipboard%2Cjquery-core%2Cjquery-migrate%2Czxcvbn-async%2Cwp-hooks\n</script>\n<script src=\"http://localhost/literasi/wp-admin/load-scripts.php?c=1&#038;load%5Bchunk_0%5D=clipboard,jquery-core,jquery-migrate,zxcvbn-async,wp-hooks&#038;ver=7.1.4\"></script>\n<script id=\"wp-i18n-js\" src=\"http://localhost/literasi/wp-includes/js/dist/i18n.min.js?ver=1dfe7db3940c23ea9216\"></script>\n<script id=\"wp-i18n-js-after\">\nwp.i18n.setLocaleData( { \'text direction\\u0004ltr\': [ \'ltr\' ] } );\n//# sourceURL=wp-i18n-js-after\n</script>\n<script id=\"password-strength-meter-js-extra\">\nvar pwsL10n = {\"unknown\":\"Kekuatan sandi tak diketahui\",\"short\":\"Sangat lemah\",\"bad\":\"Lemah\",\"good\":\"Sedang\",\"strong\":\"Kuat\",\"mismatch\":\"Tidak sama\"};\n//# sourceURL=password-strength-meter-js-extra\n</script>\n<script id=\"password-strength-meter-js-translations\">\n( function( domain, translations ) {\n	var localeData = translations.locale_data[ domain ] || translations.locale_data.messages;\n	localeData[\"\"].domain = domain;\n	wp.i18n.setLocaleData( localeData, domain );\n} )( \"default\", {\"translation-revision-date\":\"2026-05-23 17:39:24+0000\",\"generator\":\"GlotPress\\/4.1.0\",\"domain\":\"messages\",\"locale_data\":{\"messages\":{\"\":{\"domain\":\"messages\",\"plural-forms\":\"nplurals=2; plural=n > 1;\",\"lang\":\"id\"},\"%1$s is deprecated since version %2$s! Use %3$s instead. Please consider writing more inclusive code.\":[\"%1$s telah kedaluarsa sejak versi %2$s! Gunakan %3$s sebagai gantinya. Silakan pertimbangkan untuk menulis kode yang lebih inklusif.\"]}},\"comment\":{\"reference\":\"wp-admin\\/js\\/password-strength-meter.js\"}} );\n//# sourceURL=password-strength-meter-js-translations\n</script>\n<script id=\"password-strength-meter-js\" src=\"http://localhost/literasi/wp-admin/js/password-strength-meter.min.js?ver=7.1.4\"></script>\n<script id=\"underscore-js\" src=\"http://localhost/literasi/wp-includes/js/underscore.min.js?ver=1.13.8\"></script>\n<script id=\"wp-util-js-extra\">\nvar _wpUtilSettings = {\"ajax\":{\"url\":\"/literasi/wp-admin/admin-ajax.php\"}};\n//# sourceURL=wp-util-js-extra\n</script>\n<script id=\"wp-util-js\" src=\"http://localhost/literasi/wp-includes/js/wp-util.min.js?ver=7.1.4\"></script>\n<script id=\"wp-dom-ready-js\" src=\"http://localhost/literasi/wp-includes/js/dist/dom-ready.min.js?ver=3fe927cab37bf38d6a23\"></script>\n<script id=\"wp-a11y-js-translations\">\n( function( domain, translations ) {\n	var localeData = translations.locale_data[ domain ] || translations.locale_data.messages;\n	localeData[\"\"].domain = domain;\n	wp.i18n.setLocaleData( localeData, domain );\n} )( \"default\", {\"translation-revision-date\":\"2026-07-07 08:33:25+0000\",\"generator\":\"GlotPress\\/4.1.0\",\"domain\":\"messages\",\"locale_data\":{\"messages\":{\"\":{\"domain\":\"messages\",\"plural-forms\":\"nplurals=2; plural=n > 1;\",\"lang\":\"id\"},\"Notifications\":[\"Notifikasi\"]}},\"comment\":{\"reference\":\"wp-includes\\/js\\/dist\\/a11y.js\"}} );\n//# sourceURL=wp-a11y-js-translations\n</script>\n<script id=\"wp-a11y-js\" src=\"http://localhost/literasi/wp-includes/js/dist/a11y.min.js?ver=31c6cec5a4ff7aff483d\"></script>\n<script id=\"user-profile-js-extra\">\nvar userProfileL10n = {\"user_id\":\"0\",\"nonce\":\"e9f7a20fa9\"};\n//# sourceURL=user-profile-js-extra\n</script>\n<script id=\"user-profile-js-translations\">\n( function( domain, translations ) {\n	var localeData = translations.locale_data[ domain ] || translations.locale_data.messages;\n	localeData[\"\"].domain = domain;\n	wp.i18n.setLocaleData( localeData, domain );\n} )( \"default\", {\"translation-revision-date\":\"2026-05-23 17:39:24+0000\",\"generator\":\"GlotPress\\/4.1.0\",\"domain\":\"messages\",\"locale_data\":{\"messages\":{\"\":{\"domain\":\"messages\",\"plural-forms\":\"nplurals=2; plural=n > 1;\",\"lang\":\"id\"},\"Your new password has not been saved.\":[\"Sandi baru Anda belum disimpan.\"],\"Application password has been copied to your clipboard.\":[\"Kata sandi aplikasi telah disalin ke papan klip Anda.\"],\"Caps lock is on.\":[\"Caps lock menyala.\"],\"Show\":[\"Tampilkan\"],\"Hide\":[\"Sembunyikan\"],\"Show password\":[\"Tampilkan sandi\"],\"Hide password\":[\"Sembunyikan sandi\"],\"Confirm use of weak password\":[\"Setujui penggunaan sandi yang lemah\"],\"The changes you made will be lost if you navigate away from this page.\":[\"Perubahan yang Anda buat akan hilang jika Anda meninggalkan laman ini.\"]}},\"comment\":{\"reference\":\"wp-admin\\/js\\/user-profile.js\"}} );\n//# sourceURL=user-profile-js-translations\n</script>\n<script id=\"user-profile-js\" src=\"http://localhost/literasi/wp-admin/js/user-profile.min.js?ver=7.1.4\"></script>\n<script id=\"wp-tooltip-js\" src=\"http://localhost/literasi/wp-includes/js/wp-tooltip.js?ver=7.1.4\"></script>\n	</body>\n	</html>\n	', 'off'),
