(20, 1, '2026-11-16 12:21:35', '2026-11-16 12:21:35', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"osteo-care\",\"tagName\":\"header\",\"className\":\"site-header\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"right\":\"0\",\"left\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"metadata\":{\"patternName\":\"osteo-care/hero\",\"name\":\"Hero Section\",\"categories\":[\"osteo-care\",\"featured\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"24px\",\"right\":\"24px\",\"top\":\"24px\"}}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"anchor\":\"home\"} -->\n<div class=\"wp-block-group alignfull has-base-background-color has-background\" id=\"home\" style=\"padding-top:24px;padding-right:24px;padding-left:24px\"><!-- wp:cover {\"url\":\"http://localhost/literasi/wp-content/themes/osteo-care/assets/images/2026/03/hero-banner.png\",\"id\":52,\"dimRatio\":50,\"overlayColor\":\"primary\",\"isUserOverlayColor\":true,\"sizeSlug\":\"large\",\"align\":\"full\",\"className\":\"is-light\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"24px\",\"topRight\":\"24px\",\"bottomLeft\":\"24px\",\"bottomRight\":\"24px\"}},\"spacing\":{\"padding\":{\"top\":\"118px\",\"bottom\":\"var:preset|spacing|70\",\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\"}},\"@mobile\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"},\"blockGap\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover alignfull is-light\" style=\"border-top-left-radius:24px;border-top-right-radius:24px;border-bottom-left-radius:24px;border-bottom-right-radius:24px;padding-top:118px;padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--70);padding-left:var(--wp--preset--spacing--40)\"><img class=\"wp-block-cover__image-background wp-image-52 size-large\" alt=\"\" src=\"http://localhost/literasi/wp-content/themes/osteo-care/assets/images/2026/03/hero-banner.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-primary-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|60\"},\"margin\":{\"top\":\"var:preset|spacing|60\"}},\"@mobile\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"0\"}}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:var(--wp--preset--spacing--60);padding-top:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--60)\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:heading {\"level\":1,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"white\"} -->\n<h1 class=\"wp-block-heading has-white-color has-text-color has-link-color\" style=\"margin-top:0;margin-bottom:0\">Literasi Digital</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}}},\"textColor\":\"white\",\"fontSize\":\"medium\"} -->\n<p class=\"has-white-color has-text-color has-link-color has-medium-font-size\">Selamat datang di situs Literasi Digital! Saya sangat senang Anda bisa menyempatkan waktu untuk berkunjung ke halaman ini. Di era modern di mana internet sudah menjadi kebutuhan pokok, literasi digital bukan lagi sekadar keterampilan tambahan, melainkan sebuah keharusan bagi kita semua. Situs ini hadir sebagai wadah edukasi, berbagi informasi, dan ruang refleksi mengenai bagaimana kita berinteraksi di dunia maya.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-inverted\"} -->\n<div class=\"wp-block-button is-style-inverted\"><a class=\"wp-block-button__link wp-element-button\">AYO MULAI!!!</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"style\":{\"@mobile\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"35%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:35%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"osteo-care\",\"tagName\":\"footer\",\"className\":\"site-footer\"} /-->\n\n<!-- wp:latest-posts /-->', 'Laman Depan', 'Menampilkan beranda situs Anda yang ditetapkan untuk menampilkan pos terbaru atau halaman statis. Templat Halaman Depan akan lebih diprioritaskan daripada semua templat lainnya.', 'publish', 'closed', 'closed', '', 'front-page', '', '', '2026-11-16 14:29:12', '2026-11-16 14:29:12', '', 0, 'http://localhost/literasi/index.php/2026/11/16/front-page/', 0, 'wp_template', '', 0),
